   * output ports.  Use named arguments to check subsets of the output ports.
   * @param battery_assessment method that will be called with the value of the outgoing data
   *        port 'battery_assessment'.
   */
  def check_concrete_output(battery_assessment: Drone_Lifecycle_Governor.Battery_Assessment_Value.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val battery_assessmentValue: Drone_Lifecycle_Governor.Battery_Assessment_Value.Type = get_battery_assessment().get
    if(!battery_assessment(battery_assessmentValue)) {
